sys_variable_value.value:
(function execute(inputs, outputs) {

    var queue = inputs.queue_record;

    if (!queue) {
        outputs.estimated_wait_time = 0;
    } else {
        var position = parseInt(queue.queue_position, 10) || 0;
        var averageTime = parseInt(queue.service.average_service_time, 10) || 0;

        outputs.estimated_wait_time = position * averageTime;
    }

})(inputs, outputs);

